import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Auditerra AI System: Technical Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/ai/overview.md","filePath":"docs/ai/overview.md"}'),r={name:"docs/ai/overview.md"};function o(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="auditerra-ai-system-technical-documentation" tabindex="-1">Auditerra AI System: Technical Documentation <a class="header-anchor" href="#auditerra-ai-system-technical-documentation" aria-label="Permalink to &quot;Auditerra AI System: Technical Documentation&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Auditerra AI system is a <strong>Retrieval-Augmented Generation (RAG)</strong> component designed to provide agricultural decision support. It functions as an intelligent advisor that augments the expertise of field experts and provides easily digestible, actionable guidance to farmers.</p><p>The system is not a standalone predictive model but an integrated layer within the broader Auditerra platform, ingesting structured soil diagnostic data and returning context-aware technical reports and SMS summaries.</p><h2 id="jupyter-notebook" tabindex="-1">Jupyter Notebook <a class="header-anchor" href="#jupyter-notebook" aria-label="Permalink to &quot;Jupyter Notebook&quot;">​</a></h2><blockquote><p><em>Click below to view the end-to-end cleaning and preprocessing of dataset</em></p></blockquote><p><a href="https://colab.research.google.com/drive/1mU0dlV3plXEzP9Kj7BLSZ703Q7xVn0NC?usp=sharing#scrollTo=gBa1yLeS3zJJ" target="_blank" rel="noreferrer"><strong>View the Notebook</strong></a></p><h2 id="_2-models-used" tabindex="-1">2. Models Used <a class="header-anchor" href="#_2-models-used" aria-label="Permalink to &quot;2. Models Used&quot;">​</a></h2><h3 id="_2-1-generative-model" tabindex="-1">2.1 Generative Model <a class="header-anchor" href="#_2-1-generative-model" aria-label="Permalink to &quot;2.1 Generative Model&quot;">​</a></h3><p>The system utilizes a Google Gemini Flash model for text generation and reasoning. This model is responsible for synthesizing the retrieved agricultural context and structured soil data into two distinct, user-specific outputs.</p><h3 id="_2-2-embedding-model" tabindex="-1">2.2 Embedding Model <a class="header-anchor" href="#_2-2-embedding-model" aria-label="Permalink to &quot;2.2 Embedding Model&quot;">​</a></h3><p>To enable semantic retrieval, the system uses the <code>gemini-embedding-2</code> model. This model converts the pre-processed agricultural reference documents into vector representations, allowing the system to understand and retrieve context relevant to specific soil measurements.</p><h3 id="_2-3-knowledge-base-store" tabindex="-1">2.3 Knowledge Base Store <a class="header-anchor" href="#_2-3-knowledge-base-store" aria-label="Permalink to &quot;2.3 Knowledge Base Store&quot;">​</a></h3><p>The agricultural reference information is indexed within a dedicated <strong>Gemini File Search Store</strong>. This acts as the system&#39;s &quot;brain,&quot; containing pre-loaded, verified agricultural datasets, crop recommendations, and soil reference materials formatted as Markdown documents.</p><hr><h2 id="_3-training-approach" tabindex="-1">3. Training Approach <a class="header-anchor" href="#_3-training-approach" aria-label="Permalink to &quot;3. Training Approach&quot;">​</a></h2><p><strong>Auditerra does not perform any custom model training or fine-tuning.</strong></p><p>Instead, it relies on <strong>RAG (Retrieval-Augmented Generation)</strong>:</p><ul><li><strong>Preparation:</strong> Raw agricultural data (including crop yield, climate, soil, and environmental factors) is cleaned, processed, and verified to create a structured knowledge base.</li><li><strong>Indexing:</strong> This knowledge base is uploaded to the Gemini File Search Store.</li><li><strong>Inference:</strong> When a request is made, relevant chunks of the indexed knowledge base are retrieved dynamically and fed to the generative model alongside the specific diagnostic data.</li></ul><p>This architecture allows the system to remain highly accurate and adaptable without the need for periodic retraining of the underlying AI model.</p><hr><h2 id="_4-data-pipeline" tabindex="-1">4. Data Pipeline <a class="header-anchor" href="#_4-data-pipeline" aria-label="Permalink to &quot;4. Data Pipeline&quot;">​</a></h2><p>The flow of data from raw information to the final user output follows a highly structured pipeline:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Raw Agricultural Datasets</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Data Processing &amp; Verification</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Markdown Knowledge-Base Documents</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Gemini File Search Store (Embedding Index)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>FastAPI Backend (Input Assembly &amp; Authorization)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Gemini Model (Retrieval + Generation)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Structured JSON Output Validation</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Distinct Delivery Channels (Expert vs. Farmer)</span></span></code></pre></div><hr><h2 id="_5-integration-with-the-auditerra-system" tabindex="-1">5. Integration with the Auditerra System <a class="header-anchor" href="#_5-integration-with-the-auditerra-system" aria-label="Permalink to &quot;5. Integration with the Auditerra System&quot;">​</a></h2><p>The AI component is deeply integrated into the backend&#39;s post-diagnostic workflow. It receives validated input from the core modules and delivers its outputs through distinct system channels.</p><h3 id="_5-1-input-authorization" tabindex="-1">5.1 Input &amp; Authorization <a class="header-anchor" href="#_5-1-input-authorization" aria-label="Permalink to &quot;5.1 Input &amp; Authorization&quot;">​</a></h3><p>The AI endpoint is strictly gated. Only authorized field experts with ownership of the specific diagnostic log can trigger the AI generation. The system extracts soil parameters (pH, N, P, K) and the issue category from the core application modules.</p><h3 id="_5-2-data-anonymization" tabindex="-1">5.2 Data Anonymization <a class="header-anchor" href="#_5-2-data-anonymization" aria-label="Permalink to &quot;5.2 Data Anonymization&quot;">​</a></h3><p>Before data leaves the trusted application zone, all personally identifiable information (PII) is strictly stripped. The AI only receives an anonymized agricultural zone ID, ensuring that no farmer names, phone numbers, or exact GPS coordinates are exposed to external AI services.</p><h3 id="_5-3-output-generation-validation" tabindex="-1">5.3 Output Generation &amp; Validation <a class="header-anchor" href="#_5-3-output-generation-validation" aria-label="Permalink to &quot;5.3 Output Generation &amp; Validation&quot;">​</a></h3><p>The model generates a strictly formatted JSON response containing two outputs:</p><ul><li><strong>Expert Report:</strong> A comprehensive, ~350-word technical guide including Diagnosis, Severity, Remediation, Follow-up, and References.</li><li><strong>Farmer SMS:</strong> A simplified, actionable message limited to 160 characters, starting with &quot;Hello farmer.&quot;</li></ul><p>The backend validates this output against a strict schema. If the AI returns malformed data, the output is rejected, preventing corruption of the core system.</p><h3 id="_5-4-delivery-channels" tabindex="-1">5.4 Delivery Channels <a class="header-anchor" href="#_5-4-delivery-channels" aria-label="Permalink to &quot;5.4 Delivery Channels&quot;">​</a></h3><p>The AI outputs are dispatched through separate, established system channels:</p><ol><li><strong>Farmer SMS:</strong> The short, validated message is sent via the SMS Leopard gateway to the farmer&#39;s mobile phone.</li><li><strong>Expert Report:</strong> The detailed technical report is dispatched via the configured expert webhook to the field expert&#39;s mobile application.</li></ol><h3 id="_5-5-auditability" tabindex="-1">5.5 Auditability <a class="header-anchor" href="#_5-5-auditability" aria-label="Permalink to &quot;5.5 Auditability&quot;">​</a></h3><p>Every generated recommendation is securely stored in PostgreSQL. The system records a SHA-256 hash of the input prompt, the output response, and the specific AI model version used. This creates a fully auditable, tamper-evident trail for every AI interaction, ensuring accountability.</p><hr><h2 id="_6-evaluation-method" tabindex="-1">6. Evaluation Method <a class="header-anchor" href="#_6-evaluation-method" aria-label="Permalink to &quot;6. Evaluation Method&quot;">​</a></h2><p>The AI system is evaluated based on its <strong>operational integrity and functionality</strong> within the application, rather than standard predictive accuracy metrics.</p><p>The primary evaluations include:</p><ul><li><strong>Retrieval Functionality:</strong> Verifying that the system correctly retrieves specific facts (e.g., crop counts, class data) from the indexed knowledge base.</li><li><strong>Format Compliance:</strong> Ensures the AI reliably returns valid JSON conforming to the system&#39;s strict schema.</li><li><strong>Integration Stability:</strong> Testing the end-to-end flow from input validation through to SMS and webhook delivery, ensuring data integrity across all system boundaries.</li></ul><hr><h2 id="_7-accuracy-results" tabindex="-1">7. Accuracy Results <a class="header-anchor" href="#_7-accuracy-results" aria-label="Permalink to &quot;7. Accuracy Results&quot;">​</a></h2><p>As a RAG-based generative system, there is <strong>no formal classification accuracy percentage</strong> (e.g., 95% accuracy) assigned to the model. The system&#39;s accuracy is inherently tied to the quality and comprehensiveness of the pre-indexed knowledge base. The documented results confirm that:</p><ul><li>The retrieval layer is fully functional.</li><li>The generative model produces structured, valid outputs.</li><li>The delivery mechanisms operate reliably.</li></ul><hr><h2 id="_8-known-limitations" tabindex="-1">8. Known Limitations <a class="header-anchor" href="#_8-known-limitations" aria-label="Permalink to &quot;8. Known Limitations&quot;">​</a></h2><h3 id="_8-1-knowledge-base-dependency" tabindex="-1">8.1 Knowledge-Base Dependency <a class="header-anchor" href="#_8-1-knowledge-base-dependency" aria-label="Permalink to &quot;8.1 Knowledge-Base Dependency&quot;">​</a></h3><p>The quality of the generated recommendations depends entirely on the quality and coverage of the uploaded agricultural reference documents. Gaps in the knowledge base can lead to suboptimal recommendations.</p><h3 id="_8-2-generative-variability" tabindex="-1">8.2 Generative Variability <a class="header-anchor" href="#_8-2-generative-variability" aria-label="Permalink to &quot;8.2 Generative Variability&quot;">​</a></h3><p>As a generative model, it can produce slightly varying outputs given the same inputs. Auditerra mitigates this by setting a low temperature parameter (0.2) to enforce consistency.</p><h3 id="_8-3-lack-of-formal-diagnostic-benchmark" tabindex="-1">8.3 Lack of Formal Diagnostic Benchmark <a class="header-anchor" href="#_8-3-lack-of-formal-diagnostic-benchmark" aria-label="Permalink to &quot;8.3 Lack of Formal Diagnostic Benchmark&quot;">​</a></h3><p>The system has not yet been evaluated against a strictly labeled, expert-validated test set. Therefore, its exact &quot;real-world agronomic accuracy&quot; is yet to be established.</p><h3 id="_8-4-sms-length-constraint" tabindex="-1">8.4 SMS Length Constraint <a class="header-anchor" href="#_8-4-sms-length-constraint" aria-label="Permalink to &quot;8.4 SMS Length Constraint&quot;">​</a></h3><p>The 160-character limitation on the farmer-facing SMS inherently restricts the depth of guidance that can be communicated to the end-user.</p><h3 id="_8-5-external-dependencies" tabindex="-1">8.5 External Dependencies <a class="header-anchor" href="#_8-5-external-dependencies" aria-label="Permalink to &quot;8.5 External Dependencies&quot;">​</a></h3><p>The AI pipeline relies on external cloud APIs (Google Gemini) and communication gateways (SMS Leopard). A failure in these external services results in a &quot;pending&quot; or &quot;failed&quot; delivery state within the system.</p><h3 id="_8-6-human-oversight" tabindex="-1">8.6 Human Oversight <a class="header-anchor" href="#_8-6-human-oversight" aria-label="Permalink to &quot;8.6 Human Oversight&quot;">​</a></h3><p>The AI acts strictly as a decision-support tool. The field expert remains completely responsible for interpreting the AI-generated report and making the final agronomic decisions.</p>`,63)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
